def test_every_existing_public_export_is_the_original_canonical_object():
    for package_name, expected in CONTRACT.items():
        package = importlib.import_module(package_name)
        assert package.__all__ == expected['all']
        if expected['version'] is not None:
            assert package.__version__ == expected['version']
        for name, (module, attribute) in expected['exports'].items():
            assert getattr(package, name) is getattr(importlib.import_module(module, package_name), attribute)
        assert set(expected['all']) <= set(dir(package))


def test_star_import_introspection_pickle_and_submodule_access():
    import anyfem
    namespace = {}
    exec('from anyfem import *', namespace)
    assert set(anyfem.__all__) <= namespace.keys()
    for name in anyfem.__all__:
        assert namespace[name] is getattr(anyfem, name)
    for value in (anyfem.Project, anyfem.GeometryModel, anyfem.solve_linear_static, anyfem.NativeMeshBackend):
        assert pickle.loads(pickle.dumps(value)) is value
    assert anyfem.geometry is importlib.import_module('anyfem.geometry')
    assert anyfem.solve is importlib.import_module('anyfem.solve')
    assert anyfem.geometry.construction is importlib.import_module('anyfem.geometry.construction')
    try:
        anyfem.this_is_not_a_public_name
    except AttributeError:
        pass
    else:
        raise AssertionError('unknown name was accepted')


def test_cold_job_process_import_does_not_load_application_or_geometry_construction():
    code = "import anyfem.job_process,sys; assert 'anyfem.scripting' not in sys.modules; assert 'anyfem.application' not in sys.modules; assert 'anyfem.geometry.construction' not in sys.modules; assert 'anyfem.solve' not in sys.modules"
    result = subprocess.run([sys.executable, '-B', '-c', code], capture_output=True, text=True, timeout=30)
    assert result.returncode == 0, result.stderr


def test_cold_import_orders_keep_geometry_construction_cycle_closed():
    for statement in ('from anyfem.model.project import Project; from anyfem import ConstructionTask',
                      'from anyfem.geometry import ConstructionTask; from anyfem import Project'):
        result = subprocess.run([sys.executable, '-B', '-c', statement], capture_output=True, text=True, timeout=30)
        assert result.returncode == 0, result.stderr


